using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ForgeLeaderboardChecks {
 const string Pending="ForgeLeaderboardChecks.Pending";static double started;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 [InitializeOnLoadMethod] static void Setup(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool(Pending,false)){SessionState.SetBool(Pending,false);new GameObject("Leaderboard checks").AddComponent<ForgeCraftMotion>().StartCoroutine(Run());}};}
 public static void RunBatch(){Directory.CreateDirectory("Artifacts/Leaderboard");SessionState.SetBool(Pending,true);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);started=EditorApplication.timeSinceStartup;EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup-started>150){Debug.LogError("Leaderboard check timeout");EditorApplication.Exit(1);}};EditorApplication.EnterPlaymode();}
 static IEnumerator Run(){var stack=new Stack<IEnumerator>();stack.Push(Checks());while(stack.Count>0){var current=stack.Peek();bool more;try{more=current.MoveNext();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);yield break;}if(!more){(current as IDisposable)?.Dispose();stack.Pop();continue;}if(current.Current is IEnumerator nested)stack.Push(nested);else yield return current.Current;}Debug.Log("LEADERBOARD_PASS");EditorApplication.Exit(0);}
 static ForgeMvp preview;
 static void DrawPreview(){if(!preview)return;var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(ForgeMvp).GetField("codeStyle",flags).SetValue(preview,new GUIStyle{font=AssetDatabase.LoadAssetAtPath<Font>("Assets/UI/NotoSansKR.ttf")});typeof(ForgeMvp).GetMethod("DrawTitle",flags).Invoke(preview,null);}
 static IEnumerator CheckUI(){
 var gui=new GameObject("Title preview GUI").AddComponent<ForgeLeaderboardPreview>();gui.Draw=DrawPreview;var owner=new GameObject("Title preview");owner.SetActive(false);preview=owner.AddComponent<ForgeMvp>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var camera=new GameObject("Title preview camera",typeof(Camera));camera.GetComponent<Camera>().backgroundColor=ForgeTitleStyle.Background;camera.GetComponent<Camera>().clearFlags=CameraClearFlags.SolidColor;var c=owner.AddComponent<ForgeLeaderboardClient>();c.Open();typeof(ForgeMvp).GetField("leaderboard",flags).SetValue(preview,c);c.Data.name="가나다라마바사아자차카타파하검왕";c.Data.cached=new ForgeLeaderboardScores{results=new[]{new ForgeLeaderboardEntry{rank=0,score=int.MaxValue,metadata=new ForgeLeaderboardName{name=c.Data.name}}}};
 try{foreach(var size in new[]{new Vector2Int(640,480),new Vector2Int(800,600),new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(3840,2160)}){Screen.SetResolution(size.x,size.y,false);foreach(int page in new[]{0,5}){typeof(ForgeMvp).GetField("titlePage",flags).SetValue(preview,page);for(int i=0;i<5;i++)yield return null;var picture=ScreenCapture.CaptureScreenshotAsTexture();if(picture){File.WriteAllBytes("Artifacts/Leaderboard/title-"+size.x+"-"+page+".png",picture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(picture);}else File.AppendAllText("Artifacts/Leaderboard/ui-results.txt","Rendered IMGUI at "+size+" page="+page+"; batch capture unavailable.\n");}}}finally{preview=null;UnityEngine.Object.DestroyImmediate(gui.gameObject);UnityEngine.Object.DestroyImmediate(owner);UnityEngine.Object.DestroyImmediate(camera);}
 }
 static IEnumerator Checks(){
  bool had=PlayerPrefs.HasKey(ForgeLeaderboardData.BestKey);int prior=PlayerPrefs.GetInt(ForgeLeaderboardData.BestKey);var config=ScriptableObject.CreateInstance<ForgeLeaderboardSettings>();config.enabledForPlayers=true;config.leaderboardId="test-"+Guid.NewGuid();string key="MakeYourItem.Leaderboard."+config.Key;
  var root=new GameObject("Leaderboard transport checks");var client=root.AddComponent<ForgeLeaderboardClient>();int calls=0,posts=0;double remote=0;bool offline=false,slow=false;
  IEnumerator Fake(string method,string url,string body,Action<long,string> reply){calls++;if(slow){yield return new WaitForSeconds(30);reply(500,"");yield break;}yield return null;if(offline){reply(0,"");yield break;}if(url.Contains("authentication")){reply(200,"{\"userId\":\"tester\",\"idToken\":\"test-token\",\"sessionToken\":\"test-session\"}");yield break;}if(method=="POST"){posts++;var payload=JsonUtility.FromJson<Payload>(body);remote=Math.Max(remote,payload.score);reply(200,"{\"score\":"+remote+"}");yield break;}if(url.Contains("/players/")){reply(remote==0?404:200,"{\"score\":"+remote+",\"metadata\":{\"name\":\"테스터\"}}");yield break;}reply(200,"{\"results\":[{\"rank\":0,\"score\":"+remote+",\"metadata\":{\"name\":\"테스터\"}}]}");}
  client.TestRequest=Fake;
  try{
   PlayerPrefs.DeleteKey(ForgeLeaderboardData.BestKey);Check(!ForgeLeaderboardData.Record(100,true,true)&&!ForgeLeaderboardData.Record(100,false,false),"exclude practice and unfinished");Check(ForgeLeaderboardData.Record(100,true,false)&&!ForgeLeaderboardData.Record(50,true,false)&&!ForgeLeaderboardData.Record(100,true,false),"max only");Check(calls==0,"sales do not contact server");
   var gameRoot=new GameObject("Actual sale");gameRoot.SetActive(false);var game=gameRoot.AddComponent<ForgeMvp>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var shop=(ForgeShop)typeof(ForgeMvp).GetField("shop",flags).GetValue(game);var sword=new ForgeProduct("sale",0,true,ForgeTraits.None,0,1,1,new ForgeItemData{handle=2,smithSaleMultiplier=3.25});int id=shop.Add(sword);int price=ForgePricing.Quote(sword).SalePrice;Check((bool)typeof(ForgeMvp).GetMethod("SellProductInternal",flags).Invoke(game,new object[]{id}),"actual sale");Check(ForgeLeaderboardData.Best==price,"actual multiplier included");Check(!(bool)typeof(ForgeMvp).GetMethod("SellProductInternal",flags).Invoke(game,new object[]{id}),"cannot sell twice");UnityEngine.Object.DestroyImmediate(gameRoot);
   client.Open(config);Check(calls==0,"first name screen offline");client.Data.name="테스터";client.Sync();while(client.Busy)yield return null;Check(posts==1&&remote==price&&client.Data.cached.results.Length==1,"first upload and fetch");
   client.Close();yield return new WaitForSecondsRealtime(5.1f);client.Open(config);while(client.Busy)yield return null;Check(posts==1,"same best not reposted");client.Close();Check(ForgeLeaderboardData.Load(config.Key).sessionToken=="test-session","identity saved");
   ForgeLeaderboardData.Record(price+200,true,false);int before=calls;yield return null;Check(calls==before,"offline improved score stays local");yield return new WaitForSecondsRealtime(5.1f);offline=true;client.Open(config);while(client.Busy)yield return null;Check(posts==1&&ForgeLeaderboardData.Best==price+200&&client.Data.cached.results.Length==1,"offline keeps pending and cache");client.Close();offline=false;
   yield return new WaitForSecondsRealtime(5.1f);client.Open(config);while(client.Busy)yield return null;Check(posts==2&&remote==price+200,"retry sends higher best");client.Close();
   yield return new WaitForSecondsRealtime(5.1f);slow=true;client.Open(config);yield return null;client.Close();before=calls;yield return null;Check(!client.Busy&&calls==before,"closing cancels requests");
   config.enabledForPlayers=false;client.Open(config);client.Sync();Check(!client.Busy&&calls==before,"unconfigured offline");client.Close();
   Check(ForgeLeaderboardData.CleanName("<b>홍길동</b>\n").IndexOf('<')<0,"name markup stripped");
   yield return CheckUI();
   File.WriteAllText("Artifacts/Leaderboard/results.txt","PASS actual single-sword sale with multiplier, max-only local storage, no offline calls, first registration, no redundant posts, identity/cache persistence, offline pending retry, cancellation and disabled configuration. Mock HTTPS responses; live cloud not configured.");
  }finally{client.Close();UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(config);PlayerPrefs.DeleteKey(key);if(had)PlayerPrefs.SetInt(ForgeLeaderboardData.BestKey,prior);else PlayerPrefs.DeleteKey(ForgeLeaderboardData.BestKey);PlayerPrefs.Save();}
 }
 [Serializable] sealed class Payload {public int score;}
}
